def cls(n):
    n=re.sub(r'[^A-Z0-9 \-]',' ',n)
    for k,r in EX.items():
        if k=='soap': continue
        if k=='haircolour_chem':
            if r.search(n) and not re.search(r'\b(COLOR PROTECT|PROTECAO DA COR|COR PROTEGIDA)\b',n): return k
            continue
        if k=='fragrance' and r.search(n):
            return 'home_fragrance' if HOME.search(n) else 'fragrance'
        if r.search(n): return k
    if HAIR.search(n): return 'hair'
    if FACE.search(n): return 'face'
    if EX['soap'].search(n): return 'soap'
    if BODY.search(n): return 'body'
    return 'other'
